package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamThaatTheoryBank2 {
    private const val T = "ථාට දහය හා රාග න්‍යාය මූලධර්ම"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("රාගයක වාදී ස්වරයට ඇති සුවිශේෂී කාර්යභාරය කුමක්ද?", "රාගයේ ප්‍රධාන හඳුනාගැනීමේ සහ රස ජනන ස්වරය වීම", "රාගයෙන් සම්පූර්ණයෙන් බැහැර කරන ස්වරය වීම", "මන්ද්‍ර සප්තකයේ පමණක් වැයීම", "තාලයේ ඛාලි ස්ථානය පෙන්වීම", "වාදී ස්වරය රාගයේ වැඩි වාර ගණනක් යෙදෙමින් ප්‍රධාන රසය මතු කරයි."),
        q("රාග වර්ගීකරණයේදී 'ශෘංගාර' හා 'චපල' රසය ප්‍රධාන වන අර්ධ ශාස්ත්‍රීය ගායන ශෛලිය කුමක්ද?", "ඨුම්රි (Thumri)", "ධෲපද් (Dhrupad)", "ලක්ෂණ ගීත", "වේද ගීතිකා", "කාෆි, ඛමාජ් සහ පීලු වැනි රාගවලින් ගයන හැඟීම්බර ශෛලිය ඨුම්රියයි."),
        q("ඛයාල් ගායන ශෛලියේ ප්‍රභේද දෙක හඳුන්වන නිවැරදි නම් මොනවාද?", "විලම්බිත ඛයාල් සහ ද්‍රුත ඛයාල්", "පූර්වාංග ඛයාල් සහ උත්තරාංග ඛයාල්", "ඕඩව ඛයාල් සහ ෂාඩව ඛයාල්", "ශුද්ධ ඛයාල් සහ විකෘති ඛයාල්", "මන්දගාමීව ගයන බඩා ඛයාල් (විලම්බිත) සහ වේගවත් චෝටා ඛයාල් (ද්‍රුත) ප්‍රභේද දෙකකි."),
        q("හෝලි වසන්ත උත්සවය තේමා කරගෙන මාත්‍රා 14 ක තාලයෙන් ගයන සම්භාව්‍ය ගායන අංගය කුමක්ද?", "ධමාර්", "තාරානා", "පැල් කවි", "ගසල්", "ධමාර් තාලයෙන් (මාත්‍රා 14) ගයන රාධා-කෘෂ්ණ වසන්ත ගීත ධමාර් නම් වේ."),
        q("සම්පූර්ණ සප්තකයක් භාවිත කරන ථාට දහයෙන් සාමාන්‍යයෙන් කෝමල ස්වර කිසිවක් නොයෙදෙන ථාට දෙක මොනවාද?", "බිලාවල් සහ කල්‍යාණ්", "කාෆි සහ ඛමාජ්", "භෛරව් සහ භෛරවී", "තෝඩි සහ පූර්වි", "බිලාවල්හි සියලු ස්වර ශුද්ධ වන අතර කල්‍යාණ්හි තීව්‍ර මධ්‍යමය පමණක් යෙදේ."),
        q("සෑම ථාටයකම විකෘති ස්වර අතර 'කෝමල රිෂභය' ඇතුළත් වන ථාට හතර කුමක්ද?", "භෛරව්, පූර්වි, මාරවා, තෝඩි සහ භෛරවී", "බිලාවල්, කල්‍යාණ්, ඛමාජ්, කාෆි", "ඛමාජ්, කාෆි, අසාවරී, කල්‍යාණ්", "බිලාවල්, ඛමාජ්, අසාවරී, කාෆි", "සන්ධිප්‍රකාශ ථාට 3 සමඟ තෝඩි සහ භෛරවී ථාටවල කෝමල රිෂභය පවතී."),
        q("ආරෝහණයේදී ස්වර 5ක් සහ අවරෝහණයේදී ස්වර 6ක් ඇති රාගයක ජාතිය නිවැරදිව කෙසේ හඳුන්වයිද?", "ඕඩව - ෂාඩව", "ෂාඩව - ඕඩව", "ඕඩව - සම්පූර්ණ", "ෂාඩව - සම්පූර්ණ", "ආරෝහණ 5 (ඕඩව) සහ අවරෝහණ 6 (ෂාඩව) බැවින් ඕඩව-ෂාඩව වේ."),
        q("ආරෝහණයේදී ස්වර 7ක් සහ අවරෝහණයේදී ස්වර 5ක් යෙදෙන රාගයක ජාතිය කුමක්ද?", "සම්පූර්ණ - ඕඩව", "ඕඩව - සම්පූර්ණ", "සම්පූර්ණ - ෂාඩව", "ෂාඩව - සම්පූර්ණ", "පළමුව ආරෝහණයේ සම්පූර්ණ (7) හා දෙවනුව අවරෝහණයේ ඕඩව (5) ලෙස දක්වයි."),
        q("ආරෝහණයේදී ස්වර 7ක් සහ අවරෝහණයේදී ස්වර 6ක් ඇති රාග ජාතිය කුමක්ද?", "සම්පූර්ණ - ෂාඩව", "ෂාඩව - සම්පූර්ණ", "ෂාඩව - ඕඩව", "ඕඩව - සම්පූර්ණ", "ආරෝහණය සම්පූර්ණ හා අවරෝහණය ස්වර හයක් (ෂාඩව) වන ජාතිය මෙයයි."),
        q("රාග විස්තාරයේදී කෙටි වාක්‍ය ඛණ්ඩයක මෙන් මන්ද්‍ර ස්වරයේ සිට ක්‍රමයෙන් ස්වර එක බැගින් වර්ධනය කරමින් ගැයීම කුමක්ද?", "විස්තාරය හෙවත් බඩ්හත්", "ද්‍රුත තානය", "චෞගුන් ලයකාරිය", "තිහායි වැයීම", "බඩ්හත් යනු ක්‍රමයෙන් ඉහළ ස්වර කරා රාගය පියවරෙන් පියවර විහිදුවා හැරීමයි."),
        q("රාගයක් ගායනය කරන විට මුළු සප්තකයෙන්ම ස්වර වක්‍රව හෙවත් ඇදවී ගමන් කිරීම හඳුන්වන්නේ කෙසේද?", "වක්‍ර ස්වර ගමන", "සරල ස්වර ගමන", "ස්ථායි ගමන", "වර්ජිත ගමන", "සෘජු පිළිවෙළ වෙනුවට 'ම ප ග ම රි ස' ලෙස හැරී යාම වක්‍ර ගමනකි."),
        q("නවීන ථාට ක්‍රමයේදී 'බිලාවල්, කල්‍යාණ්, ඛමාජ්' යන ථාට තුන පොදුවේ වෙන් වී ඇත්තේ කුමන ලක්ෂණයකින්ද?", "කෝමල රි සහ කෝමල ධ රහිත වීම", "මධ්‍යමය සම්පූර්ණයෙන් වර්ජිත වීම", "කෝමල ස්වර හතරක් තිබීම", "ෂඩ්ජය විකෘති වීම", "කෝමල ග, ධ, රි රහිත ශුද්ධ රි-ධ පදනම් ථාට ගණයට මේවා අයත් වේ."),
        q("සප්තකයේ ස්වර 7න් වර්ජිත ස්වර 2ක් ඇති විට එම ස්වර මාලාව හැඳින්වෙන ජාතිය කුමක්ද?", "ඕඩව", "ෂාඩව", "සම්පූර්ණ", "චතුර්ස්වර", "ස්වර 7න් 2ක් අඩු වූ විට ස්වර 5ක් ඉතිරි වන බැවින් එය ඕඩව වේ."),
        q("සප්තකයේ ස්වර 7න් වර්ජිත ස්වර 1ක් පමණක් ඇති කොටස කුමන ජාතියට අයත්ද?", "ෂාඩව", "ඕඩව", "සම්පූර්ණ", "අතිතාර", "ස්වර 1ක් අත්හැර ස්වර 6කින් යුත් කොටස ෂාඩව ජාතිය නම් වේ."),
        q("භාත්ඛණ්ඩේ ථාට 10 අතුරින් 'කාෆි, අසාවරී, භෛරවී' යන ථාට තුනේම පොදුවේ යෙදෙන කෝමල ස්වර යුගලය මොනවාද?", "කෝමල ග සහ කෝමල නි", "කෝමල රි සහ තීව්‍ර ම්", "කෝමල ධ සහ තීව්‍ර ම්", "කෝමල රි සහ කෝමල ධ", "කාෆි (ග̱, නි̱), අසාවරී (ග̱, ධ̱, නි̱) සහ භෛරවී (රි̱, ග̱, ධ̱, නි̱) යන තුනේම ග̱ හා නි̱ පවතී."),
        q("සන්ධිප්‍රකාශ රාග කාණ්ඩයට අයත් 'තීව්‍ර මධ්‍යමය' සහිත ථාට දෙක මොනවාද?", "පූර්වි සහ මාරවා", "භෛරව් සහ බිලාවල්", "කාෆි සහ ඛමාජ්", "අසාවරී සහ භෛරවී", "සවස සන්ධිප්‍රකාශ වේලාවේ ගයන පූර්වි සහ මාරවා ථාට දෙකේම තීව්‍ර ම් යෙදේ."),
        q("පහත දැක්වෙන ථාටවලින් පූර්ණ හෙවත් ශුද්ධ රි-ග-ධ-නි යෙදී මධ්‍යමය පමණක් තීව්‍ර වන ථාටය කුමක්ද?", "කල්‍යාණ් ථාටය", "පූර්වි ථාටය", "තෝඩි ථාටය", "මාරවා ථාටය", "තීව්‍ර ම් හැර අනෙක් සියලු ස්වර ශුද්ධ වන්නේ කල්‍යාණ් ථාටයේය."),
        q("යම් රාගයක ප්‍රධාන අංගයන් ගැඹුරින් විස්තර කිරීමේදී මූලිකවම සැලකිල්ලට ගන්නා න්‍යායාත්මක කරුණු මොනවාද?", "ථාටය, ජාතිය, වාදී-සංවාදී, වර්ජිත ස්වර සහ ගායන සමය", "තාලයේ ඨේකාව සහ දුගුන් බෝල් පමණක්", "නර්තන මුද්‍රා සහ රංග වස්ත්‍රාභරණ", "බෙර සම්ප්‍රදාය සහ ගුරුකුල නාමයන්", "ඕනෑම රාගයක ලක්ෂණ විවරණය මෙම ප්‍රධාන සිද්ධාන්ත 5 මත පදනම් වේ."),
        q("පෙරදිග සංගීතයේ 'රාගය' යන වචනයේ ශාස්ත්‍රීය නිර්වචනය වන 'රංජයති ඉති රාගඃ' යන්නේ අර්ථය කුමක්ද?", "මිනිස් සිත ප්‍රීතිමත් කරමින් රස ගන්වන ස්වර රටාව", "තාල මාත්‍රා ගණනය කරන ගණිත ක්‍රමය", "වාද්‍ය භාණ්ඩ සුසර කරන යතුරු පද්ධතිය", "ජන කවි ගැයීමේ ශබ්ද තරංග මාපකය", "සිත රංජනය කරන හෙවත් සිත් ඇදගන්නා ස්වර සංයෝජනය රාගය නම් වේ."),
        q("කිසියම් රාගයක 'මූලික අනන්‍යතාවය' බිඳ නොවැටී රැකගැනීම සඳහා ගායකයා කළ යුත්තේ කුමක්ද?", "ආරෝහණ, අවරෝහණ, වාදී-සංවාදී සහ පකඩ රීති රැකීම", "හැකි තරම් වේගයෙන් තාන් පමණක් ගැයීම", "වර්ජිත ස්වර නිතර නිතර ගායනා කිරීම", "තාලය අතහැර නාට්‍ය පද කීම", "රාගයේ නියමිත ස්වර සීමා හා පකඩ රටාව ආරක්ෂා කිරීම අනිවාර්ය වේ."),
        q("එක් ථාටයකින් උපරිම වශයෙන් විවිධ රාග කීයක් පමණ නිර්මාණය විය හැකිද?", "ගණන් කළ නොහැකි විශාල රාග සංඛ්‍යාවක්", "හරියටම එක් රාගයක් පමණක්", "උපරිම වශයෙන් රාග දෙකක් පමණක්", "හරියටම රාග නවයක් පමණක්", "ස්වර වර්ජන හා වාදී-සංවාදී වෙනස්කම් අනුව එක් ථාටයකින් රාග සිය ගණනක් බිහි වේ."),
        q("රාග සංගීතයේදී 'ප්‍රබන්ධ' ගීත අතර ගැඹුරු භක්ති රසය පළ කරන සරල සාම්ප්‍රදායික ගීත විශේෂය කුමක්ද?", "භජන්", "ධමාර්", "තාරානා", "කපිරිඤ්ඤා", "භජන් ගීත කහර්වා හෝ දාද්‍රා තාලවලින් සුගම රාග ඇසුරෙන් ගැයේ."),
        q("රාගයක අන්තිම හෙවත් නිමාවේදී එක්වරම සම ('X') වෙත පැමිණීම සඳහා තුන් වරක් පුනරුච්චාරණය කරන රටාව කුමක්ද?", "තිහායි", "අලාප", "ස්ථායි", "ජවාරි", "තාන් හෝ බෝල් රටාවක් සමානව තුන් වරක් ගයා සමට වැටීම තිහායි වේ."),
        q("දවසේ රාත්‍රී දෙවන ප්‍රහරය (රාත්‍රී 9–12) තුළ ගැයීමට වඩාත් උචිත රාග කාණ්ඩය කුමක්ද?", "ඛමාජ්, කාෆි සහ බාගේශ්‍රී වැනි රාග", "භෛරව් සහ තෝඩි වැනි ප්‍රභාත රාග", "බිලාවල් සහ සාරංග වැනි උදෑසන රාග", "පූර්වි සහ මාරවා වැනි සන්ධ්‍යා රාග", "රාත්‍රී මධ්‍ය ප්‍රහරවලදී ඛමාජ් හා කාෆි ථාටවල රාග බහුලව ගැයේ."),
        q("පූර්ව භාරතීය ග්‍රන්ථවල සඳහන් 'වර්තමාන ගීත ප්‍රසංගයක' පළමුව ඉදිරිපත් කරන විලම්බිත රාග විස්තරය කුමක්ද?", "නොම්-තොම් අලාපය", "ද්‍රුත තාරානා", "චතුර්ගුණ තාලය", "නාට්‍ය පෙරවදන", "තාල රහිතව 'නොම්, තොම්, තාන, රෙ' වැනි අක්ෂර යොදා රාග අලාපය කෙරේ."),
        q("පණ්ඩිත් භාත්ඛණ්ඩේ මැතිඳුන් ථාට 10 ක්‍රමය හඳුන්වා දීමෙන් පසු පාසල් සංගීත අධ්‍යාපනයට ලැබුණු ප්‍රධාන වාසිය කුමක්ද?", "ස්වර සමානතාව අනුව රාග පහසුවෙන් වර්ග කර ඉගෙනීමට හැකි වීම", "රාග ගායන සමය සම්පූර්ණයෙන් අහෝසි වීම", "ශුද්ධ ස්වර වෙනුවට කෝමල ස්වර පමණක් භාවිත වීම", "තාල පද්ධතිය ඉවත් කිරීමට හැකි වීම", "විද්‍යාත්මක ස්වර ව්‍යුහය අනුව ඕනෑම රාගයක් ථාටයකට ගොනු කිරීම පහසු විය."),
        q("සෑම ථාටයකම කිසිදු වෙනසක් නොමැතිව ගමන් කළ යුතු ස්වර පිළිවෙළ කුමක්ද?", "ස, රි, ග, ම, ප, ධ, නි යන ක්‍රමානුකූල අනුපිළිවෙළ", "ප, ම, ග, රි, ස යන අවරෝහණ පිළිවෙළ", "ස, ග, ප, නි යන වක්‍ර පිළිවෙළ", "ස, රි, ප, ධ යන පංච ස්වර පිළිවෙළ", "ථාටයක ස්වර 7 ක්‍රමයෙන් ආරෝහණ අනුපිළිවෙළට පැවතීම අනිවාර්ය නියමයකි."),
        q("පුරාණ ගායන රීතියේ සඳහන් 'භාව රසය' මතු කිරීම සඳහා රාගයකට තිබිය යුතු ප්‍රධාන ලක්ෂණය කුමක්ද?", "නිවැරදි ස්වර උච්චාරණය හා ගායන සමයට ගැළපීම", "වාද්‍ය භාණ්ඩ සියල්ල එකවර වේගයෙන් වැයීම", "අත්පුඩි ශබ්දය උපරිම කිරීම", "වචන නොමැතිව කෑගසා ගැයීම", "රාගයේ නියමිත රසය මතු වන්නේ සුදුසු ස්වර රටා හා මනෝභාවයෙනි."),
        q("කිසියම් රාගයක 'ගායන සමය' නියම කිරීමට බලපාන මූලික න්‍යායාත්මක සාධක දෙක මොනවාද?", "විකෘති ස්වර (කෝමල/තීව්‍ර) සහ වාදී ස්වරයේ පිහිටීම", "තාලයේ මාත්‍රා ගණන සහ ඛාලි සංඛ්‍යාව", "ගායකයාගේ වයස සහ හඬ පරාසය", "වාද්‍ය භාණ්ඩයේ දැව වර්ගය සහ තන්තු ගණන", "ස්වර ලක්ෂණ (අධිවර්ෂක/සන්ධිප්‍රකාශ) සහ වාදී පිහිටීම රාග වේලාව තීරණය කරයි."),
        q("දහවල් කාලයේ (පෙ.ව. 10 සිට ප.ව. 4 දක්වා) සාමාන්‍යයෙන් ගයනු ලබන රාගවල බහුලව යෙදෙන කෝමල ස්වර මොනවාද?", "කෝමල ග සහ කෝමල නි", "කෝමල රි සහ කෝමල ධ", "කෝමල රි සහ තීව්‍ර ම්", "කෝමල ධ සහ තීව්‍ර ම්", "අසාවරී, ජෞන්පුරි, බීම්පලාසි වැනි දහවල් රාගවල ග̱ හා නි̱ බහුලව දක්නට ලැබේ."),
        q("එක් සප්තකයක සිට ඊළඟ සප්තකය දක්වා 'විස්තාරය' ගොඩනඟන විට මන්ද්‍ර, මධ්‍ය සහ තාර යන කලාප තුනම ගැයීම කුමක් පෙන්වයිද?", "රාගයක සම්පූර්ණ විහිදීම (ප්‍රස්තාර විස්තාරය)", "රාගයක ජාතිය ඕඩව බව", "තාලයේ සම නොමැති බව", "විකෘති ස්වර අත්හැරීම", "දක්ෂ ශිල්පියෙකු සප්තක තුනේම රාග ස්වරූපය පැහැදිලිව විහිදුවයි."),
        q("'ස' සහ 'ම' අතර හෝ 'ස' සහ 'ප' අතර ස්ථාපිත වන රාගයේ ප්‍රධාන සමතුලිතතා නියමය කුමක්ද?", "සංවාදිත්ව න්‍යාය", "තාල දශප්‍රාණ න්‍යාය", "සාරණා චතුෂ්ටය", "අවග්‍රහ න්‍යාය", "වාදී-සංවාදී ස්වර අතර පවතින පරතර න්‍යාය සංවාදිත්වයයි."),
        q("රාගයක අංග ලෙස 'චලනය' පෙන්වන වක්‍ර ස්වර භාවිතයේ අරමුණ කුමක්ද?", "රාගයට අනන්‍ය වූ චමත්කාරජනක හැඩය මතු කිරීම", "සියලුම ස්වර ශුද්ධ ස්වර බවට පත් කිරීම", "තාලයේ මාත්‍රා අඩු කිරීම", "ගායනය ඉක්මනින් අවසන් කිරීම", "ආරෝහණ-අවරෝහණයේ ස්වර හැරී ගමන් කිරීම රාගයට අනන්‍යතාවක් දේ."),
        q("'කල්‍යාණ්' සහ 'බිලාවල්' යන ථාට දෙකම භාවිත කරමින් උපදින රාගවල පොදු ලක්ෂණය කුමක්ද?", "සියලු රි, ග, ධ, නි ස්වර ශුද්ධ ස්වර වීම", "සියලු ස්වර කෝමල වීම", "ෂඩ්ජය වර්ජිත වීම", "පංචමය තීව්‍ර වීම", "බිලාවල්හි සියල්ල ශුද්ධ වන අතර කල්‍යාණ්හි ම පමණක් තීව්‍ර වේ."),
        q("සම්පූර්ණ වේලාවන්හිදී පමණක් නොව ඕනෑම ප්‍රහරයකදී ගැයිය හැකි 'සර්වකාලීන රාගයක්' ලෙස ප්‍රකට රාගය කුමක්ද?", "භෛරවී රාගය", "යමන් රාගය", "භූපාලි රාගය", "මාරවා රාගය", "ප්‍රසංග අවසානයේදී හෝ ඕනෑම වේලාවක ගැයීමට සුදුසු සර්වකාලීන රාගයක් ලෙස භෛරවී සැලකේ."),
        q("සංගීත සභාවක් අවසන් කිරීමේ සම්ප්‍රදායක් ලෙස ඉන්දීය හා ලාංකේය රසිකයින් ඉදිරියේ අවසානයට ගයන රාගය කුමක්ද?", "භෛරවී රාගය", "තෝඩි රාගය", "පූර්වි රාගය", "භෛරව් රාගය", "භෛරවී රාගයෙන් ශාස්ත්‍රීය ප්‍රසංග නිමා කිරීම සාම්ප්‍රදායික චාරිත්‍රයකි."),
        q("පුරාණ ඉන්දීය 'රාග-රාගිනී' ක්‍රමයේදී ප්‍රධාන පුරුෂ රාග ලෙස සැලකුණු රාග සංඛ්‍යාව කොපමණද?", "රාග 6 කි", "රාග 10 කි", "රාග 12 කි", "රාග 7 කි", "භෛරව්, මාල්කෞන්ස්, හින්ඩෝල්, දීපක්, ශ්‍රී හා මේඝ යන ප්‍රධාන රාග 6ක් පැවතුණි."),
        q("කල්‍යාණ් ථාටයේ ප්‍රධානතම සහ ප්‍රසිද්ධම ආශ්‍රය රාගය ලෙස හඳුන්වන්නේ කුමන රාගයද?", "යමන් රාගය (කල්‍යාණ්)", "කාෆි රාගය", "ඛමාජ් රාගය", "භෛරව් රාගය", "කල්‍යාණ් ථාටයේ ලක්ෂණ සියල්ල නියෝජනය කරන මූලික රාගය යමන් රාගයයි."),
        q("බිලාවල් ථාටයේ මූලික රාග ලක්ෂණ නිරූපණය කරන රාගය කුමක්ද?", "අල්හෛයා බිලාවල්", "භූපාලි", "යමන්", "අසාවරී", "බිලාවල් රාගය බිලාවල් ථාටයේ ආශ්‍රය රාගයයි."),
        q("භෛරවී ථාටයේ ස්වර 7න් විකෘති වන කෝමල ස්වර ගණන කොපමණද?", "4 කි", "2 කි", "3 කි", "1 කි", "රි̱, ග̱, ධ̱, නි̱ යන කෝමල ස්වර හතරක් භෛරවී ථාටයේ යෙදේ."),
        q("පූර්වි ථාටයේ අඩංගු වන විකෘති ස්වර සංඛ්‍යාව මුළුමනින්ම කීයද?", "3 කි", "1 කි", "2 කි", "5 කි", "කෝමල රි, කෝමල ධ සහ තීව්‍ර ම යන විකෘති ස්වර තුනක් පූර්වි ථාටයේ පවතී."),
        q("තෝඩි ථාටයේ යෙදෙන මුළු විකෘති ස්වර සංඛ්‍යාව කොපමණද?", "4 කි", "2 කි", "3 කි", "1 කි", "කෝමල රි, ග, ධ සහ තීව්‍ර ම් ලෙස විකෘති ස්වර හතරක් තෝඩි ථාටයේ පවතී."),
        q("මාරවා ථාටයේ යෙදෙන මුළු විකෘති ස්වර ගණන කොපමණද?", "2 කි", "4 කි", "3 කි", "1 කි", "කෝමල රිෂභය සහ තීව්‍ර මධ්‍යමය යන විකෘති ස්වර දෙක මාරවා ථාටයේ ඇත."),
        q("බිලාවල් ථාටය තුළ යෙදෙන විකෘති ස්වර ගණන කොපමණද?", "0 කි (කිසිවක් නැත)", "2 කි", "4 කි", "1 කි", "බිලාවල් ථාටයේ සියලුම ස්වර ශුද්ධ ස්වර වේ."),
        q("ඛමාජ් ථාටයේ ඇති විකෘති ස්වර සංඛ්‍යාව කොපමණද?", "1 කි", "2 කි", "3 කි", "4 කි", "ඛමාජ් ථාටයේ කෝමල නිෂාදය (නි̱) පමණක් විකෘති ස්වරයකි."),
        q("කල්‍යාණ් ථාටයේ අඩංගු විකෘති ස්වර ගණන කොපමණද?", "1 කි", "3 කි", "2 කි", "4 කි", "කල්‍යාණ් ථාටයේ තීව්‍ර මධ්‍යමය (ම්) පමණක් විකෘති ස්වරය වේ."),
        q("භෛරව් ථාටයේ සහ කාෆි ථාටයේ යෙදෙන විකෘති ස්වර ගණන බැගින් කොපමණද?", "2 බැගින්", "3 බැගින්", "4 බැගින්", "1 බැගින්", "භෛරව්හි රි-ධ ද කාෆිහි ග-නි ද වශයෙන් විකෘති ස්වර දෙක බැගින් ඇත."),
        q("අසාවරී ථාටයේ ඇති මුළු විකෘති ස්වර ගණන කොපමණද?", "3 කි", "2 කි", "4 කි", "1 කි", "කෝමල ග, ධ, නි යන විකෘති ස්වර තුන අසාවරී ථාටයේ ඇත."),
        q("දවසේ 'මධ්‍යහ්න' (දහවල් 12–3) සහ 'මධ්‍යම රාත්‍රී' (රාත්‍රී 12–3) ප්‍රහර දෙකෙහි ගැයෙන රාග සඳහා වැදගත් වන ස්වරය කුමක්ද?", "සාමාන්‍යයෙන් කෝමල ග සහ කෝමල නි", "කෝමල රි සහ කෝමල ධ පමණක්", "තීව්‍ර ම පමණක්", "කෝමල රි සහ තීව්‍ර ම", "සන්ධි කාලවලින් බැහැර මධ්‍යම කාලවල ග̱ හා නි̱ සහිත රාග ප්‍රධාන වේ."),
        q("රාගයක් ඕඩව ජාතියේ වීම සඳහා එහි ආරෝහණයේ හෝ අවරෝහණයේ තිබිය යුතු ස්වර ගණන කීයද?", "5 කි", "6 කි", "7 කි", "4 කි", "ඕඩව යනු පංච ස්වර (5) පදනමයි."),
        q("රාගයක් ගැයීමේදී තම හඬ හා මනෝභාවය කැටිකොට ඉදිරිපත් කරන 'ගායනා දොස්' අතරින් වැළකිය යුතු දෝෂය කුමක්ද?", "අපස්වර වීම හා රාග සීමා බිඳීම", "මීණ්ඩ් හා කණ ස්වර යෙදීම", "තම්බුරාව සුසර කර ගැයීම", "වාදී ස්වරය මත රැඳී සිටීම", "වර්ජිත ස්වර යෙදීම හා අපස්වර වීම ගායනයේ ප්‍රධාන දෝෂ වේ."),
        q("ශාස්ත්‍රීය බණ්ඩිසයක් ඉගෙනීමට පෙර ශිෂ්‍යයෙකු එම රාගයේ පදනම අවබෝධ කර ගැනීමට ගැයිය යුත්තේ මොනවාද?", "ආරෝහණ, අවරෝහණ, පකඩ සහ සර්ගම් ගීත", "නූර්ති හා නාඩගම් දෙබස්", "පැල් හා කරත්ත කවි", "ලෝහ ඝන වාද්‍ය භාණ්ඩ", "රාගයේ ආරෝහණ, අවරෝහණ, පකඩ හා සර්ගම් ගැයීමෙන් රාග ස්වරූපය පැහැදිලි වේ."),
        q("රාගයක 'පකඩ' සමන්විත වන්නේ සාමාන්‍යයෙන් ස්වර කීයක පමණ කුඩා රටාවකින්ද?", "ස්වර 4 සිට 8 දක්වා කෙටි රටාවකින්", "සම්පූර්ණ සප්තක 3ක දීර්ඝ ගීතයකින්", "එක් තනි ස්වරයකින් පමණක්", "මාත්‍රා 64ක දීර්ඝ තානයකින්", "පකඩ යනු රාගයේ ස්වභාවය වහා හඳුනාගැනීමට සෑහෙන කෙටි ස්වර කණ්ඩයකි."),
        q("සංගීතයේ 'රස නිෂ්පත්තිය' යන්නෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "රාගය හා ගීතය තුළින් ශ්‍රාවක මනසෙහි හැඟීම්බර ආස්වාදයක් ඉපදීම", "තාලයේ මාත්‍රා ගණන නිවැරදිව ලිවීම", "වාද්‍ය භාණ්ඩ අලුත්වැඩියා කිරීම", "ස්වර ලිපි කටපාඩම් කිරීම", "කරුණා, ශෘංගාර, ශාන්ත වැනි රසයන් ශ්‍රාවක හදවතේ ජනිත වීම රස නිෂ්පත්තියයි."),
        q("උත්තර භාරතීය රාගධාරී සංගීතයේ රාග අධ්‍යයනය කිරීමෙන් සිසුවාට ලැබෙන ප්‍රධානම හැකියාව කුමක්ද?", "ශ්‍රැති ශුද්ධිය, නිර්මාණශීලී ස්වර හැසිරවීම හා රසඥතාව", "බටහිර පියානෝ යතුරු අලුත්වැඩියා කිරීම", "නූතන ශබ්ද පටිගත කිරීමේ මෘදුකාංග සෑදීම", "විදේශීය නර්තන වර්ග පුහුණු වීම", "රාග අධ්‍යයනය කන් පුහුණුව, හඬ පාලනය හා කලාත්මක නිර්මාණශීලීත්වය වර්ධනය කරයි."),
        q("සාමාන්‍යයෙන් ශුද්ධ ස්වර වැඩි රාග සහ කෝමල ස්වර වැඩි රාග ගැයෙන වේලා අතර සබඳතාව කුමක්ද?", "විකෘති ස්වර වෙනස් වීම අනුව රාගයේ දවසේ ප්‍රහරය මාරු වේ", "සියලු රාග උදෑසන 6ටම ගැයේ", "විකෘති ස්වර ඇති රාග රාත්‍රියේ නොගැයේ", "ශුද්ධ ස්වර රාග කිසිදා නොගැයේ", "ස්වර වෙනස්කම් මත පදනම්ව රාග ඒ ඒ ප්‍රහරයන්ට වෙන් කර ඇත."),
        q("උත්තර භාරතීය සංගීතයේ ථාට 10 ක්‍රමයට 'ජනක - ජන්‍ය' වාදය වැදගත් වන්නේ ඇයි?", "ථාටය ජනක (උපදවන) ලෙසත් රාගය ජන්‍ය (උපදින) ලෙසත් සම්බන්ධ වන බැවින්", "තාලය සහ වාද්‍ය භාණ්ඩ එකට බැඳෙන බැවින්", "ජන ගී සහ නූර්ති එකතු වන බැවින්", "ගුරුවරයා සහ සිසුවා මාරු වන බැවින්", "ජනක ථාටය මව වන අතර ඉන් බිහිවන ජන්‍ය රාග එහි දරුවන් බඳුය."),
        q("යම් රාගයක 'වාදී' ස්වරය දන්නා විට සාමාන්‍යයෙන් එහි 'සංවාදී' ස්වරය පිහිටන්නේ කෙසේද?", "වාදී ස්වරයට සප්තකයේ සිව්වන හෝ පස්වන ස්ථානයේය", "වාදී ස්වරයට යාබද අර්ධ ස්වරයේය", "රාගයෙන් බැහැර වර්ජිත ස්ථානයේය", "තාර සප්තකයේ පමණක් පිහිටයි", "ෂඩ්ජ-මධ්‍යම (4/5 වන) හෝ ෂඩ්ජ-පංචම (5/6 වන) ස්වර පරතරය අනුව සංවාදී ස්වරය පිහිටයි."),
        q("රාග විස්තාරයේදී 'චරණ' හෝ 'ස්වර කණ්ඩ' ගොඩනැඟීමේදී ඒවා අවසන් කිරීම සඳහා ප්‍රමුඛව යොදාගන්නා ස්වර මොනවාද?", "ස, වාදී සහ සංවාදී ස්වර", "විවාදී සහ වර්ජිත ස්වර", "තීව්‍ර සහ කෝමල ස්වර පමණක්", "මන්ද්‍ර ධෛවතය පමණක්", "න්‍යාස හෙවත් විරාම ස්වර ලෙස බොහෝ විට ස, වාදී හෝ සංවාදී ස්වර යොදයි."),
        q("උත්තර භාරතීය ශාස්ත්‍රීය සංගීතයේ රාගයක් ගොඩනැගීමේදී අවම වශයෙන් තිබිය යුතු ස්වර සංඛ්‍යාව කීයද?", "ස්වර 5 කි", "ස්වර 2 කි", "ස්වර 12 කි", "ස්වර 3 කි", "සාමාන්‍යයෙන් රාගයක් පැවතීමට අවම වශයෙන් ස්වර පහක් (ඕඩව) අවශ්‍ය බව පිළිගැනේ."),
        q("ඕනෑම රාගයක උපරිම වශයෙන් ආරෝහණ හෝ අවරෝහණ පිළිවෙළකට යෙදිය හැකි ස්වර ගණන කීයද?", "ස්වර 7 කි (සම්පූර්ණ)", "ස්වර 5 කි", "ස්වර 4 කි", "ස්වර 3 කි", "ශුද්ධ සප්ත ස්වර 7ට අනුරූපව ආරෝහණ හා අවරෝහණ පෙළෙහි ස්වර 7ක් පිහිටයි."),
        q("'අසාවරී' ථාටය හා 'කාෆි' ථාටය සංසන්දනය කිරීමේදී අසාවරී ථාටයේ අමතරව කෝමල වන ස්වරය කුමක්ද?", "ධෛවතය (ධ̱)", "රිෂභය (රි̱)", "මධ්‍යමය (ම්)", "පංචමය", "කාෆි ථාටයේ ග-නි කෝමල වන අතර අසාවරීහි ග-ධ-නි කෝමල වේ."),
        q("'ඛමාජ්' ථාටය සහ 'බිලාවල්' ථාටය අතර පවතින එකම ස්වර වෙනස කුමක්ද?", "ඛමාජ්හි නිෂාදය කෝමල වන අතර බිලාවල්හි නිෂාදය ශුද්ධ වේ", "ඛමාජ්හි ග කෝමල වේ", "බිලාවල්හි ම තීව්‍ර වේ", "ඛමාජ්හි රි කෝමල වේ", "ශුද්ධ ස්වර හතෙන් නිෂාදය පමණක් කෝමල වීමෙන් ඛමාජ් ථාටය සෑදේ."),
        q("තෝඩි ථාටයේ හා භෛරවී ථාටයේ විකෘති ස්වර 4 බැගින් තිබුණද ඒවා වෙනස් වන්නේ කුමන ස්වර දෙකෙන්ද?", "තෝඩිහි ම තීව්‍ර හා නි ශුද්ධ වන අතර භෛරවීහි ම ශුද්ධ හා නි කෝමල වේ", "තෝඩිහි රි ශුද්ධ වන අතර භෛරවීහි රි කෝමල වේ", "තෝඩිහි ස වර්ජිත වේ", "භෛරවීහි ප වර්ජිත වේ", "තෝඩි (රි̱ ග̱ ම් ධ̱) සහ භෛරවී (රි̱ ග̱ ධ̱ නි̱) යන ස්වර සැකැස්ම වෙනස් වේ."),
        q("'කාෆි' ථාටයේ ස්වර මාලාව නිවැරදිව දැක්වෙන පිළිතුර කුමක්ද?", "ස රි ග̱ ම ප ධ නි̱ සඃ", "ස රි ග ම ප ධ නි සඃ", "ස රි ග ම් ප ධ නි සඃ", "ස රි̱ ග ම ප ධ̱ නි සඃ", "ගාන්ධාරය සහ නිෂාදය කෝමල වී සෙසු ස්වර ශුද්ධ වීම කාෆි ථාටයයි."),
        q("'අසාවරී' ථාටයේ ස්වර මාලාව නිවැරදිව දැක්වෙන්නේ කුමන වරණයේද?", "ස රි ග̱ ම ප ධ̱ නි̱ සඃ", "ස රි̱ ග̱ ම ප ධ̱ නි̱ සඃ", "ස රි ග ම ප ධ නි̱ සඃ", "ස රි̱ ග ම් ප ධ̱ නි සඃ", "ග, ධ සහ නි යන ස්වර තුන කෝමල වී අනෙක් ස්වර ශුද්ධ වීම අසාවරී ථාටයයි."),
        q("'භෛරවී' ථාටයේ ස්වර මාලාව නිවැරදිව දැක්වෙන පිළිතුර තෝරන්න.", "ස රි̱ ග̱ ම ප ධ̱ නි̱ සඃ", "ස රි̱ ග ම ප ධ̱ නි සඃ", "ස රි ග̱ ම් ප ධ නි̱ සඃ", "ස රි ග ම ප ධ නි සඃ", "සියලුම චල කෝමල ස්වර හතර (රි̱, ග̱, ධ̱, නි̱) සහ ශුද්ධ ම භෛරවී ථාටයේ යෙදේ."),
        q("'භෛරව්' ථාටයේ ස්වර මාලාව නිවැරදිව දැක්වෙන්නේ කුමක්ද?", "ස රි̱ ග ම ප ධ̱ නි සඃ", "ස රි̱ ග̱ ම ප ධ̱ නි̱ සඃ", "ස රි ග ම ප ධ නි සඃ", "ස රි̱ ග ම් ප ධ̱ නි සඃ", "රිෂභය හා ධෛවතය කෝමල වී ගාන්ධාර, මධ්‍යම හා නිෂාදය ශුද්ධ වේ."),
        q("'පූර්වි' ථාටයේ ස්වර මාලාව නිවැරදිව දැක්වෙන පිළිතුර කුමක්ද?", "ස රි̱ ග ම් ප ධ̱ නි සඃ", "ස රි̱ ග ම ප ධ̱ නි සඃ", "ස රි ග ම් ප ධ නි සඃ", "ස රි̱ ග̱ ම් ප ධ̱ නි සඃ", "කෝමල රි, තීව්‍ර ම සහ කෝමල ධ සහිතව ග හා නි ශුද්ධ වීම පූර්වි ථාටයයි."),
        q("රාග විස්තාරයේදී 'පූර්වාංග' කොටසේ ස්වර වැඩිපුර ගායනා කරන විට ගායනය රැඳී පවතින්නේ කුමන පරාසයේද?", "මන්ද්‍ර හා මධ්‍ය සප්තකයේ පහළ ස්වරවල (ස සිට ප දක්වා)", "තාර සප්තකයේ ඉහළම ස්වරවල", "ස සිට තාර ප දක්වා පමණක්", "නිහඬව තාල ගණන් කිරීමේ", "පූර්වාංග ප්‍රධාන රාගවල වර්ධනය මන්ද්‍ර නි සිට මධ්‍ය ප දක්වා බහුලව සිදු කෙරේ."),
        q("රාග ගායනයේදී 'තිරෝභාව' (Tirobhava) යන ශාස්ත්‍රීය යෙදුමෙන් අදහස් කරන්නේ කුමක්ද?", "ප්‍රධාන රාගයේ ස්වරූපය තාවකාලිකව සඟවා සමීප වෙනත් රාග ඡායාවක් පෙන්වීම", "තාලය සම්පූර්ණයෙන් අමතක කිරීම", "මන්ද්‍ර සප්තකයෙන් ආරම්භ කිරීම", "තම්බුරාව සුසර කිරීම", "ප්‍රවීණ ශිල්පීන් ප්‍රධාන රාගය සඟවා යළි ආවිර්භාව මගින් රාගය මතු කර පෙන්වයි."),
        q("තිරෝභාවයෙන් පසුව නැවත මුල් රාගයේ පැහැදිලි ස්වරූපය ඉස්මතු කර පෙන්වීම කුමක්ද?", "ආවිර්භාව (Avirbhava)", "වර්ජිත බව", "විවාදී බව", "ඛාලි බව", "අන්‍ය රාග ඡායාව මගහැර මුල් රාගයේ පකඩ ස්වර මගින් මුල් රාගය යළි ප්‍රකට කිරීම ආවිර්භාව වේ."),
        q("දක්ෂිණ භාරතීය කර්ණාටක සංගීතයේ 'මේලකර්තා 72' පද්ධතිය සහ හින්දුස්ථානි 'ථාට 10' අතර ඇති සමානකම කුමක්ද?", "දෙකම රාග වර්ගීකරණය සඳහා සැකසූ ජනක ස්වර පද්ධති වීම", "දෙකෙහිම තබ්ලා බෝල් අඩංගු වීම", "දෙකේම ගණන 10ක් පමණක් වීම", "දෙකම බටහිර ඔපෙරාවට සෑදීම", "ජනක-ජන්‍ය ක්‍රමයෙන් රාග විද්‍යාත්මකව පෙළගැස්වීම පද්ධති දෙකෙහිම අරමුණයි."),
        q("එක් ථාටයක් යටතේ බිහිවිය හැකි උපරිම රාග සංඛ්‍යාව ගණිතමය ලෙස කොපමණ වේදැයි පැරණි ග්‍රන්ථවල සඳහන්ද?", "484 කි", "10 කි", "7 කි", "60 කි", "ඕඩව, ෂාඩව, සම්පූර්ණ සංයෝජන අනුව එක් මේලයකින් ජන්‍ය රාග 484ක් ගොඩනැගිය හැකිය."),
        q("ඒ අනුව භාත්ඛණ්ඩේගේ ථාට 10 ඇසුරෙන් සෛද්ධාන්තිකව බිහිකළ හැකි මුළු රාග ගණන කීයක්ද?", "4840 කි", "100 කි", "220 කි", "720 කි", "ථාට 10 × 484 බැගින් 4840ක් වුවද ප්‍රායෝගිකව භාවිත වන්නේ ඉන් සිය ගණනකි."),
        q("'භූපාලි' සහ 'දේශ්කාර්' යන රාග දෙකේම එකම ස්වර 5 (ස රි ග ප ධ) යෙදුණද ඒවා වෙනස් වන්නේ කුමකින්ද?", "වාදී-සංවාදී ස්වර, අංගය හා ගායන වේලාව මත", "වර්ජිත ස්වර වෙනස් වීම මත", "ජාතිය වෙනස් වීම මත", "තාලය වෙනස් වීම මත", "භූපාලි රාත්‍රී පූර්වාංග (වාදී ග) වන අතර දේශ්කාර් උදෑසන උත්තරාංග (වාදී ධ) රාගයකි."),
        q("රාගයක 'ප්‍රකෘති බව' සහ 'රසය' රැඳී ඇති කෙටි ස්වර සමූහය හඳුන්වන 'මුඛ්‍යාංගය' යනු කුමක්ද?", "පකඩ (Pakad)", "තාන (Taan)", "අන්තරා", "මන්ද්‍ර ස්ථානය", "රාගය හඳුනාගැනීමේ ප්‍රධාන ස්වර සලකුණ වන පකඩය මුඛ්‍යාංගය ලෙසද හැඳින්වේ."),
        q("රාග විස්තාරයේදී 'චලන' (Chalan) යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "රාගයේ සම්පූර්ණ ගමන් මග පෙන්වන ස්වර විස්තරය", "තබ්ලාව වාදනය කරන මූලික ලය වේගය", "වේදිකාව මත ශිල්පියා ගමන් කරන ආකාරය", "තම්බුරාවේ තන්තු හතර සුසර කිරීමේ ක්‍රමය", "රාගයේ ආරෝහණ, අවරෝහණ හා වක්‍ර චලනයන් චලන තුළින් පැහැදිලිව නිරූපණය කෙරේ."),
        q("උත්තර භාරතීය රාග කලාවේ 'මුර්ඡනා' (Moorchhana) යන පැරණි සංකල්පයෙන් අදහස් කළේ කුමක්ද?", "එක් එක් ස්වරය ආරම්භක ෂඩ්ජය කර නව ස්වර මාලා සෑදීම", "රාග ගායනය අතරමැද හදිසියේ නතර කිරීම", "මද්දල හා තබ්ලා බෝල් පද වාදනය කිරීම", "රාගයකට අදාළ සාහිත්‍ය ගී පද රචනා කිරීම", "පැරණි ෂඩ්ජ හා මධ්‍යම ග්‍රාමවලින් නව ස්වර පෙළ නිපදවීමට මුර්ඡනා ක්‍රමය භාවිත විය."),
        q("නූතන භාත්ඛණ්ඩේ රාග පද්ධතිය පැමිණීමට පෙර භාරතීය රාග වර්ගීකරණය සඳහා තිබූ පැරණි ක්‍රමය කුමක්ද?", "රාග - රාගිනී ක්‍රමය (Raga-Ragini System)", "බටහිර මේජර්-මයිනර් ක්‍රමය", "පංචතූර්ය ක්‍රමය", "සරල ගී ක්‍රමය", "රාග 6ක් සහ රාගිනී 30 හෝ 36ක් වශයෙන් පුරුෂ-ස්ත්‍රී ස්වරූපයෙන් පැරණි වර්ගීකරණය පැවතිණි."),
        q("පැරණි 'රාග - රාගිනී' වර්ගීකරණය වෙනුවට භාත්ඛණ්ඩේතුමා ථාට 10 ක්‍රමය ගෙන ආවේ ඇයි?", "මතභේද නැති විද්‍යාත්මක ස්වර පදනමක් අවශ්‍ය වූ නිසා", "පවතින රාග සංඛ්‍යාව සම්පූර්ණයෙන් අඩු කිරීමට", "ශාස්ත්‍රීය ගායනයෙන් තබ්ලාව ඉවත් කර දැමීමට", "බටහිර පොප් සංගීත පරිමාණයන්ට ගැළපීමට", "විවිධ පඬිවරුන් අතර මත ගැටුම් පැවති රාග-රාගිනී ක්‍රමය වෙනුවට පැහැදිලි ථාට ක්‍රමය පිහිටුවීය."),
        q("'ලඝු - තාල - ආලාප' වැනි අංග අතුරින් රාගයේ සැබෑ මනෝභාවය කිසිදු තාල බන්ධනයකින් තොරව ගෙන එන්නේ කුමක්ද?", "ආලාපය (Alap)", "දෘත තාන", "තිහායි", "තේකා", "ආලාපය තාල රහිත නිදහස් ස්වර විහිදුවීම මගින් රාගයේ සැබෑ හැඟීම විවර කරයි."),
        q("රාගයක 'ප්‍රබල හා දුබල ස්වර' හඳුනාගැනීමට ගායනා කරනු ලබන ස්වර අභ්‍යාසය හඳුන්වන්නේ කෙසේද?", "ස්වර විස්තාර හා සර්ගම් ගීත", "බෙර අභ්‍යාස", "පිරිත් සජ්ඣායනය", "රබන් පද", "රාගයේ ස්වර හැසිරෙන ආකාරය පුහුණු වීමට සර්ගම් හා විස්තාර අභ්‍යාස කෙරේ."),
        q("උත්තර භාරතීය ශාස්ත්‍රීය සංගීතයේ 'බදත්' (Badhat) යන වචනයෙන් අදහස් කරන්නේ කුමක්ද?", "ස්වරයෙන් ස්වරය පියවරෙන් පියවර රාගය ඉහළට වර්ධනය කිරීම", "ගායනයේ ශබ්ද ප්‍රමාණය ක්‍රමයෙන් අඩු කර ගැනීම", "තාලය වේගවත් කොට හදිසියේ ගීතය අවසන් කිරීම", "ප්‍රධාන තන්තු වාද්‍ය භාණ්ඩය නිහඬ කර තැබීම", "මන්ද්‍රයේ සිට තාර දෙසට ක්‍රමානුකූලව රාගය විහිදුවා පෙන්වීම බදත් නම් වේ."),
        q("ශාස්ත්‍රීය රාගයක් ගැයීමේදී 'මූල ෂඩ්ජයෙන් (ස) පහළට' ගොස් විහිදෙන ස්වර කලාපය කුමක්ද?", "මන්ද්‍ර සප්තකය", "තාර සප්තකය", "අතිතාර සප්තකය", "මධ්‍ය සප්තකයේ ඉහළ අර්ධය", "යමන්, බාගේශ්‍රී වැනි රාගවල මන්ද්‍ර නි, ධ, ප දක්වා පහළට බැස අලංකාරය වැඩි කෙරේ."),
        q("පහත දැක්වෙන ලක්ෂණ අතුරින් රාගයක් සතුවිය යුතු අනිවාර්ය සෞන්දර්ය ගුණාංගය කුමක්ද?", "ශ්‍රාවක සිත ප්‍රීතිමත් කිරීම හෙවත් 'රංජකත්වය' (Ranjakatva)", "කර්කශ ඝෝෂාවක් ඇති කිරීම", "සියලු ස්වර 12ම එක් වර ගැයීම", "අනිවාර්යයෙන් වේගවත් බව", "'රංජයති ඉති රාගඃ' යන නිර්වචනයට අනුව සිත සතුටු කිරීම රාගයේ මූලික ගුණයයි."),
        q("රාගයක 'වාදී ස්වරය' මාරු කළහොත් සමස්ත රාගයට කුමක් සිදුවේද?", "රාගයේ ස්වරූපය, ගායන වේලාව හෝ රාගයම වෙනත් රාගයක් බවට පත්වේ", "කිසිදු වෙනසක් සිදු නොවේ", "තාලය ත්‍රිතාලයට මාරු වේ", "ථාටය සම්පූර්ණයෙන් අහෝසි වේ", "භූපාලි හා දේශ්කාර් හෝ යමන් හා කල්‍යාණ් ලෙස වාදී ස්වරය රාගය වෙනස් කරයි."),
        q("'ඡායාලග රාගයක්' ලෙස හඳුන්වනු ලබන්නේ කුමන ආකාරයේ රාගයක්ද?", "ප්‍රධාන රාගයකට අමතරව වෙනත් රාගයක සුළු ඡායාවක් පෙන්වන රාගය", "තාලයකින් තොර රාගය", "ස්වර 4ක් පමණක් ඇති රාගය", "දහවල් පමණක් ගයන රාගය", "ශුද්ධ රාගයකට වෙනත් රාග ලක්ෂණයක් මදක් මුසු වූ විට ඡායාලග නම් වේ."),
        q("'සංකීර්ණ රාගයක්' (Sankeerna Raga) යනු කුමක්ද?", "රාග දෙකක් හෝ කිහිපයක් ශාස්ත්‍රීයව මිශ්‍ර කර සැකසූ නව රාගය", "ගැයීමට නොහැකි රාගය", "බටහිර සිම්ෆනිය", "සම්පූර්ණ ස්වර 7 ඇති රාගය", "උදාහරණයක් ලෙස බසන්ත්-බහාර් හෝ යමන්-කල්‍යාණ් සංකීර්ණ රාග වේ."),
        q("බිලාවල් ථාටයේ සහ කල්‍යාණ් ථාටයේ යෙදෙන කෝමල ස්වර ගණන පිළිවෙළින් කීයද?", "0 ක් සහ 0 ක් (දෙකේම කෝමල ස්වර නැත)", "1 ක් සහ 2 ක්", "4 ක් සහ 3 ක්", "2 ක් සහ 4 ක්", "බිලාවල්හි සියල්ල ශුද්ධ වන අතර කල්‍යාණ්හි තීව්‍ර ම පමණක් ඇති බැවින් දෙකේම කෝමල ස්වර 0කි."),
        q("රාග දෙකක් 'සමප්‍රකෘතික' (සමාන ස්වර ඇති) රාග ලෙස හඳුන්වන්නේ කුමන අවස්ථාවකද?", "දෙකෙහිම එකම ථාටයේ ස්වර යෙදෙමින් වාදී හා චලනයෙන් පමණක් වෙනස් වන විට", "දෙකම විවිධ ථාටවලින් පැමිණි විට", "එකක් කර්ණාටක හා අනෙක බටහිර වන විට", "දෙකම එකම තාලයේ ඇති විට", "භූපාලි හා දේශ්කාර් හෝ කාෆි හා සින්ධුරා සමප්‍රකෘතික ස්වර ලක්ෂණ පෙන්වයි."),
        q("රාගයක් ගැයීමේදී 'තාලයේ වේගය' හා 'ගායනා කරන වේලාව' අතර ඇති සම්බන්ධය කුමක්ද?", "විවිධ ප්‍රහරවල රාගයන්හි රසභාව අනුව විලම්බ, මධ්‍ය හෝ දෘත ලය යොදාගනී", "සියලු උදෑසන රාග අති දෘත ලයෙන්ම ගැයේ", "සියලු රාත්‍රී රාග තාල රහිතව ගැයේ", "කිසිදු සම්බන්ධයක් නැත", "රාගයේ ගාම්භීර හෝ චංචල රසය අනුව ගායනයේ ලය තෝරා ගැනේ."),
        q("'රාග නියම' අනුව ඕනෑම රාගයක 'ආරෝහණ' යනු කුමක්ද?", "ස සිට තාර සං දක්වා ස්වර ක්‍රමයෙන් ඉහළට නැගෙන ගමනයි", "තාර සං සිට ස දක්වා පහළට බසින ගමනයි", "තාලයේ මාත්‍රා 16 ගණන් කිරීමයි", "තම්බුරාව සුසර කිරීමයි", "ස්වර ඉහළට ගමන් කිරීම ආරෝහණ වන අතර ආපසු පහළට ඒම අවරෝහණ වේ."),
        q("'අවරෝහණ' ගමනකදී රාගයක ස්වර ගමන් කරන දිශාව කුමක්ද?", "තාර සප්තකයේ සිට මධ්‍ය හා මන්ද්‍ර සප්තකය දෙසට පහළ බැසීම", "මන්ද්‍රයේ සිට තාර දෙසට ඉහළ යෑම", "එකම ස්වරය මත රැඳීම", "වර්ජිත ස්වර මත පැනීම", "ආරෝහණයෙන් උච්ච ස්වර වෙත ගොස් අවරෝහණයෙන් ක්‍රමයෙන් මූල ෂඩ්ජයට පැමිණේ."),
        q("රාග න්‍යාය පිළිබඳ O/L විෂය නිර්දේශය තුළ ථාට 10 ඉගෙනීමෙන් සිසුන්ට ලැබෙන ප්‍රධාන පහසුව කුමක්ද?", "රාගයක යෙදෙන ශුද්ධ හා විකෘති ස්වර වහා වර්ග කර හඳුනාගැනීම", "සියලු තබ්ලා බෝල් කටපාඩම් කිරීම", "ගැමි කවි ලිවීම", "බටහිර ඩ්‍රම්ස් වාදනය කිරීම", "රාගයක් අයත් ථාටය දන්නා විට එහි මූලික ස්වර සැකැස්ම ඉක්මනින් අවබෝධ වේ."),
        q("රාග න්‍යායට අනුව 'වර්ණ' (Varna) යනුවෙන් හඳුන්වනු ලබන ගායන ක්‍රියාවන් හතර මොනවාද?", "ස්ථායි, ආරෝහී, අවරෝහී සහ සංචාරී", "ශෘංගාර, හාස්‍ය, කරුණ හා වීර", "ආතත, විතත, ඝන හා සුසිර", "විලම්බ, මධ්‍ය, දෘත හා අතිදෘත", "එකම ස්වරයක සිටීම (ස්ථායි), ඉහළ යෑම (ආරෝහී), පහළ ඒම (අවරෝහී) හා මිශ්‍ර ගමන (සංචාරී) චතුර්විධ වර්ණ වේ.")
    )
}
